-- Deities and Demigods: Olympian pantheon divine stat blocks, batch B.
-- Source: Deities and Demigods (2002), Chapter 4, pp. 108-115.
-- Printed 3.0 statistics and source contradictions are preserved; official 3.5 conversion deltas are separate.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Bow and arrow on a lunar disk' WHERE source_id='dd-3.0' AND slug='artemis' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='An owl' WHERE source_id='dd-3.0' AND slug='athena' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Mare''s head' WHERE source_id='dd-3.0' AND slug='demeter' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Thyrsus, a staff tipped with a pine cone and twisted with a vine' WHERE source_id='dd-3.0' AND slug='dionysus' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-artemis','Artemis Divine Stat Block','108-110',
 'Artemis is the divine-rank-15 intermediate Olympian deity of hunting, wild beasts, childbirth, and dance.',
 '{"deitySlug":"artemis","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["Artemis of the Golden Shafts","Friend of Youth","Lady of the Lake","The Huntress"],"symbol":"Bow and arrow on a lunar disk","homePlane":"Olympus","alignment":"NG","classes":[{"class":"Druid","level":20},{"class":"Ranger","level":20}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+180 outsider + 20d8+180 druid + 20d10+180 ranger","hitPoints":1060,"initiative":"+19, always first","speed":{"land":80},"armorClass":{"total":79,"size":-1,"dexterity":15,"divine":15,"natural":28,"deflection":12},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"shortSword":"+70/+65/+60/+55 melee, +5 keen short sword","shortSwordDamage":"1d8+16/18-20","bow":"+84/+84/+79/+74/+69 ranged, Huge +5 mighty speed composite longbow (+11 Str) with +5 arrows","bowDamage":"2d6+36/19-20/x3","spellTouch":{"melee":65,"ranged":69}},"saves":{"fort":56,"ref":62,"will":57,"intermediateDeityChecksAlways20":true},"abilities":{"str":32,"dex":40,"con":29,"int":26,"wis":26,"cha":35},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"spellResistance":67,"divineAura":{"radiusFeet":1500,"dc":37},"favoredEnemies":"animals +5, beasts +4, magical beasts +3, aberrations +2, giants +1","wildShape":"Tiny through Huge or dire animal 6/day; elemental 3/day","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Reality","Alter Size","Area Divine Shield","Avatar","Call Creatures (animals)","Control Creatures (fey)","Divine Archery","Divine Celerity","Divine Dodge","Divine Shield","Divine Weapon Focus (composite longbow)","Divine Weapon Specialization (composite longbow)","Extra Domain (Sun)","Grow Creature (animals)","Increased Spell Resistance","Mind of the Beast","Speak with Creatures (animals)","Speak with Creatures (plants)","Supreme Initiative"],"domainPowers":{"animalFriendshipUsesPerDay":15,"goodSpellsCasterLevelBonus":1,"plantRebukeCommandUsesPerDay":15,"greaterTurningUsesPerDay":15},"spellLikeAbilities":{"casterLevel":25,"printedExceptionalCasterText":"except for law spells, which she uses as a 26th-level caster","saveDc":"37 + spell level","sourceNote":"The printed exception says law spells even though Artemis has no Law domain and is neutral good; preserve as a source copy error."},"spellcasting":{"druidSpellsPerDay":"6/7/7/7/7/6/5/5/5/4","druidBaseDc":"18 + spell level","rangerSpellsPerDay":"5/5/5/5","rangerBaseDc":"18 + spell level"},"automaticActions":{"skills":["Animal Empathy","Handle Animal","Intuit Direction","Knowledge (nature)","Listen","Profession (herbalist)","Spot","Wilderness Lore"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"initiative":19,"armorClass":63,"attacks":"short sword +63/+58/+53/+48 or bow +71/+66/+61/+56","spellTouch":{"melee":57,"ranged":61},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":29},"saves":{"fort":48,"ref":54,"will":49},"salientDivineAbilities":["Alter Form","Alter Size","Call Creatures (animals)","Divine Celerity","Divine Dodge","Divine Archery","Divine Weapon Focus (composite longbow)","Divine Weapon Specialization (composite longbow)","Extra Domain (Sun)"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"29 + spell level"},"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"25/epic","fireResistance":20,"rangerHitDice":"20d8 instead of 20d10","adjustedHitPoints":1020,"rangerSkillPointsGain":40,"rangerFavoredEnemyBonusesTotal":18,"rangerFeatures":["wild empathy","Endurance bonus feat","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"],"divineCelerity":"Functions according to revised haste.","defunctSkills":["Animal Empathy -> wild empathy","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

('dd-statblock-athena','Athena Divine Stat Block','110-112',
 'Athena is the divine-rank-17 greater Olympian deity of wisdom, crafts, civilization, and war.',
 '{"deitySlug":"athena","pantheon":"olympian","sourceEdition":"3.0","rankBand":"greater","divineRank":17,"symbol":"An owl","homePlane":"Olympus","alignment":"LG","classes":[{"class":"Fighter","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","subtypes":["Good","Lawful"],"size":"Large","printedHitDice":"20d8+140 outsider + 2d10+140 fighter + 20d8+140 cleric","printedHitPoints":940,"sourceHdConflict":"Class header is Fighter 20/Cleric 20 and 940 hp is consistent with twenty fighter Hit Dice under the deity maximum-HP convention, but the printed HD line says 2d10+140 (Ftr). The discrepancy is preserved.","initiative":13,"speed":{"land":80},"armorClass":{"total":92,"size":-1,"dexterity":9,"divine":17,"natural":30,"breastplate":10,"shield":7,"deflection":10},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"shortspear":"+74/+74/+69/+64/+59 melee, +5 holy lawful speed shortspear","damage":"1d8+32/19-20/x3; greater deity maximum 40","spellTouch":{"melee":64,"ranged":65},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":56,"ref":58,"will":66,"greaterDeityAlways20":true},"abilities":{"str":27,"dex":29,"con":25,"int":33,"wis":45,"cha":31},"specialAttacks":{"turnUndeadPerDay":13},"specialQualities":{"printedDamageReduction":"52/+4","printedFireResistance":37,"spellResistance":49,"divineAura":{"radiusMiles":17,"dc":37},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Avatar","Battlesense","Create Object","Create Greater Object","Divine Armor Mastery","Divine Battle Mastery","Divine Blast","Divine Dodge","Divine Inspiration (courage)","Divine Shield","Divine Storm","Divine Weapon Focus (shortspear)","Divine Weapon Mastery","Divine Weapon Specialization (shortspear)","Extra Domain (Community)","Extra Domain (Law)","Extra Domain (War)","Mass Divine Blast"],"domainPowers":{"creationSpellsCasterLevelBonus":1,"calmEmotionsUsesPerDay":17,"goodSpellsCasterLevelBonus":1,"divinationSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":27,"creationGoodDivinationLawCasterLevel":28,"saveDc":"37 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/11/10/10/10/10/8/8/8/8","clericBaseDc":"27 + spell level"},"possessions":{"helmet":"Adjustable 10-150 ft. antimagic field, free-action radius/on-off control; caster level 25; weight 3 lb.","shield":"When not using Aegis, +5 large steel greater-fortification shield with medusa likeness; activated gaze petrifies mortals within 150 ft., Will DC 25; caster level 25; weight 15 lb."},"automaticActions":{"skills":["Craft (pottery)","Craft (sculpture)","Craft (stoneworking)","Craft (weaving)","Knowledge (arcana)","Knowledge (architecture and engineering)","Knowledge (history)","Knowledge (religion)"],"freeActionDcMaximum":30,"maximumPerRound":20},"avatar":{"divineRank":8,"armorClass":74,"attacks":"shortspear +63/+63/+58/+53/+48, 1d8+23/x3","spellTouch":{"melee":55,"ranged":56},"damageReduction":"43/+4","fireResistance":28,"spellResistance":40,"divineAura":{"radiusFeet":800,"dc":28},"saves":{"fort":47,"ref":49,"will":57},"salientDivineAbilities":["Alter Size","Battlesense","Divine Battle Mastery","Divine Dodge","Divine Shield","Divine Weapon Focus (shortspear)","Divine Weapon Specialization (shortspear)","Extra Domain (Community)","Extra Domain (Law)","Extra Domain (War)"],"spellLikeCasterLevel":18,"spellLikeSaveDc":"28 + spell level"},"revision3_5":{"alignmentSubtypes":["good","lawful"],"damageReduction":"30/epic","fireResistance":22,"additionalOutsiderSkillPoints":true,"battlesense":"Replaces uncanny dodge and improved uncanny dodge."}}'),

('dd-statblock-demeter','Demeter Divine Stat Block','112-113',
 'Demeter is the divine-rank-10 lesser Olympian deity of agriculture and fertility.',
 '{"deitySlug":"demeter","pantheon":"olympian","sourceEdition":"3.0","rankBand":"lesser","divineRank":10,"titles":["The Gift-Giver","Lovely-Haired Demeter","Demeter of the Splendid Fruit"],"symbol":"Mare''s head","homePlane":"Olympus","alignment":"N","sourceIdentityNote":"Table 4-1 gives favored weapon Spear; the individual entry specifies Shortspear or halfspear, while the combat block uses a longspear.","classes":[{"class":"Druid","level":20},{"class":"Abjurer","level":20}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+160 outsider + 20d8+160 druid + 20d4+160 abjurer","hitPoints":880,"initiative":8,"speed":{"land":80},"armorClass":{"total":61,"size":-1,"dexterity":8,"divine":10,"natural":23,"deflection":11},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"longspear":"+67/+62/+57/+52 melee, +5 longspear","damage":"1d8+23/19-20/x3","spellTouch":{"melee":61,"ranged":57}},"saves":{"fort":50,"ref":50,"will":60},"abilities":{"str":35,"dex":26,"con":26,"int":30,"wis":43,"cha":33},"specialQualities":{"printedDamageReduction":"45/+4","printedFireResistance":30,"fastHealing":30,"spellResistance":42,"divineAura":{"radiusFeet":1000,"dc":31},"familiar":"horses","wildShape":"Tiny through Huge or dire animal 6/day; elemental 3/day","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Arcane Mastery","Avatar","Call Creatures (plants)","Command Plants","Control Creatures (plants)","Divine Fast Healing","Divine Shield","Rejuvenation","Speak with Creatures (animals)","Speak with Creatures (plants)"],"domainPowers":{"earthTurningUsesPerDay":10,"plantRebukeCommandUsesPerDay":10,"protectiveWardUsesPerDay":10,"protectiveWardResistanceBonus":10},"spellLikeAbilities":{"casterLevel":20,"saveDc":"31 + spell level"},"spellcasting":{"druidSpellsPerDay":"6/9/9/9/9/8/7/7/7/6","druidBaseDc":"26 + spell level","wizardSpellsPerDay":"5/8/8/7/7/7/7/6/6/6","wizardBaseDc":"20 + spell level","prohibitedSchool":"Illusion"},"automaticActions":{"skills":["Knowledge (arcana)","Knowledge (local)","Knowledge (nature)","Knowledge (religion)"],"freeActionDcMaximum":20,"maximumPerRound":5},"avatar":{"divineRank":5,"armorClass":51,"attacks":"longspear +62/+57/+52/+47, 1d8+23/x3","spellTouch":{"melee":56,"ranged":52},"damageReduction":"40/+4","fireResistance":25,"fastHealing":25,"spellResistance":37,"divineAura":{"radiusFeet":500,"dc":26},"saves":{"fort":45,"ref":45,"will":55},"salientDivineAbilities":["Alter Reality","Alter Size","Arcane Mastery","Command Plants","Divine Fast Healing","Divine Shield"],"spellLikeCasterLevel":15,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":[],"damageReduction":"20/epic","fireResistance":15,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules.","druid":"Apply revised wild shape and class features.","defunctSkills":["Animal Empathy -> wild empathy","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

('dd-statblock-dionysus','Dionysus Divine Stat Block','114-115',
 'Dionysus is the divine-rank-12 intermediate Olympian deity of mirth, madness, wine, fertility, and theater.',
 '{"deitySlug":"dionysus","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":12,"titles":["Women-Maddener","Ivy-Wreathed Dionysus","Loud-Roaring Dionysus"],"symbol":"Thyrsus, a staff tipped with a pine cone and twisted with a vine","homePlane":"Olympus","alignment":"CN","classes":[{"class":"Bard","level":15},{"class":"Druid","level":15},{"class":"Ranger","level":10}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+200 outsider + 15d6+150 bard + 15d8+150 druid + 10d10+100 ranger","hitPoints":1020,"initiative":15,"speed":{"land":80},"armorClass":{"total":73,"size":-1,"dexterity":11,"divine":12,"natural":25,"deflection":16},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"mainQuarterstaff":"+66/+61/+56/+51 melee, Huge +5 chaotic quarterstaff","offQuarterstaff":"+66/+61/+56 melee, Huge +5 chaotic quarterstaff","damage":"main 1d8+17; off 1d8+11","spellTouch":{"melee":61,"ranged":60}},"saves":{"fort":56,"ref":55,"will":52,"intermediateDeityChecksAlways20":true},"abilities":{"str":35,"dex":33,"con":30,"int":27,"wis":27,"cha":43},"specialQualities":{"printedDamageReduction":"47/+4","printedFireResistance":32,"fastHealing":32,"spellResistance":44,"divineAura":{"radiusFeet":1200,"dc":38},"bardicKnowledge":23,"bardicMusicPerDay":15,"favoredEnemies":"aberrations +3, magical beasts +2, vermin +1","wildShape":"Tiny through Huge or dire animal 5/day","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Avatar","Control Creatures (revelers)","Command Plants (vines only)","Divine Fast Healing","Divine Inspiration (frenzy)","Divine Shield","Empowered Inspiration (frenzy)","Mind of the Beast (slumber only)","Rejuvenation","Shapechange","True Shapechange","Water to Wine"],"uniqueAbilities":{"empoweredInspiration":"When Divine Inspiration targets creatures already in the cult''s orgiastic rites, it can affect unlimited creatures with no saving throws.","waterToWine":"Can change any amount of any liquid within sight into fine wine."},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"smiteUsesPerDay":12,"smiteAttackBonus":4,"smiteDamageBonus":12,"insanityScore":6,"wisdomForSpellcasting":33,"wisdomOtherwise":21,"clarityOfMadnessUsesPerDay":12,"clarityBonus":6},"spellLikeAbilities":{"casterLevel":22,"chaosCasterLevel":23,"saveDc":"38 + spell level"},"spellcasting":{"bardSpellsKnownPerDay":"4/8/7/7/7/5","bardBaseDc":"26 + spell level","druidSpellsPerDay":"6/7/7/7/6/5/4/3/2","druidBaseDc":"23 + spell level","rangerSpellsPerDay":"3/3","rangerBaseDc":"23 + spell level"},"automaticActions":{"skills":["Craft (winemaking)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":6,"armorClass":61,"attacks":"quarterstaff +60/+55/+50/+45 and +60/+55","spellTouch":{"melee":55,"ranged":54},"damageReduction":"41/+4","fireResistance":26,"fastHealing":26,"spellResistance":38,"divineAura":{"radiusFeet":600,"dc":32},"saves":{"fort":50,"ref":49,"will":46},"salientDivineAbilities":["Alter Reality","Alter Size","Divine Celerity","Divine Dodge","Divine Fast Healing","Divine Inspiration (frenzy)","Shapechange","Water to Wine"],"spellLikeCasterLevel":16,"spellLikeSaveDc":"32 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic"],"damageReduction":"25/epic","fireResistance":17,"rangerHitDice":"10d8 instead of 10d10","adjustedHitPoints":1000,"divineCelerity":"Functions according to revised haste.","druid":"Apply revised wild shape and class features.","ranger":"Apply revised ranger class features, skill points, favored-enemy progression, and combat style as applicable.","defunctSkills":["Animal Empathy -> wild empathy","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas and sourceNotes/sourceHdConflict preserve printed contradictions.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-olympian-pantheon',NULL,
  '["deities-and-demigods","olympian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
